<?php
/**
 * Phase 8D Finance DATABASE verification (manual only; never part of routine CI). Runs in a DISPOSABLE scratch database on a LOCAL MySQL server only.
 * Checks: migration (idempotent, additive, structure, indexes, generated unique key), CRM and submissions tables unchanged, the MySQL store against real SQL,
 * reuse of the Phase 6 revenue functions, least-privilege grants, rollback and re-apply, plus a smoke test of the Phase 8C MySQL store and migration.
 * Usage: P7_USER=root P7_PASS=... php tests/phase8d_finance_db_test.php   (host must be local; the database name always contains "test")
 */
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
$root = dirname(__DIR__); chdir($root);
$host = getenv('AIHUB_DB_HOST') ?: '127.0.0.1'; if (!in_array($host, ['127.0.0.1', 'localhost'], true)) { fwrite(STDERR, "Refusing: this test only runs against a local disposable server.\n"); exit(2); }
$user = getenv('P7_USER') ?: (getenv('AIHUB_COMPAT_ROOT_USER') ?: 'root'); $pw = getenv('P7_PASS') !== false ? getenv('P7_PASS') : (getenv('AIHUB_COMPAT_ROOT_PASS') !== false ? getenv('AIHUB_COMPAT_ROOT_PASS') : '');
$db = 'p8d_verify_' . getmypid() . '_test'; $appUser = 'fin_app_' . getmypid() . '_test'; $appPw = bin2hex(random_bytes(8));
putenv('AIHUB_SECURITY_LOG=' . sys_get_temp_dir() . '/p8d_sec_' . getmypid() . '.log'); putenv('AIHUB_RATE_DIR=' . sys_get_temp_dir() . '/p8d_rate_' . getmypid());
$opt = [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC];
$admin = new PDO("mysql:host=$host;port=3306", $user, $pw, $opt); $ver = (string)$admin->query('SELECT VERSION()')->fetchColumn();
if (stripos($ver, 'mariadb') !== false) { fwrite(STDERR, "Refusing: the server is MariaDB ($ver). MySQL is required.\n"); exit(2); }
$admin->exec("CREATE DATABASE `$db` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");
register_shutdown_function(function () use ($admin, $db, $appUser) { try { $admin->exec("DROP DATABASE IF EXISTS `$db`"); } catch (Throwable $e) {} try { $admin->exec("DROP USER IF EXISTS '$appUser'@'%'"); } catch (Throwable $e) {} });
$pdo = new PDO("mysql:host=$host;port=3306;dbname=$db", $user, $pw, $opt);
ob_start(); require_once $root . '/adm_core.php'; require_once $root . '/adm_finance_views.php'; require_once $root . '/adm_tools_views.php'; ob_end_clean();
$pass = 0; $fail = 0; function ok($c, string $m): void { global $pass, $fail; if ($c) $pass++; else { $fail++; fwrite(STDERR, "  FAIL: $m\n"); } } function section(string $t): void { fwrite(STDERR, "== $t\n"); }
function stmts(string $file): array { $b = ''; $o = []; foreach (preg_split('/\R/', (string)file_get_contents($file)) as $l) { $t = trim($l); if ($b === '' && ($t === '' || str_starts_with($t, '--'))) continue; $b .= $l . "\n"; if (str_ends_with(rtrim($b), ';')) { $o[] = substr(rtrim($b), 0, -1); $b = ''; } } return $o; }
function run(PDO $p, string $file): void { foreach (stmts($file) as $s) $p->exec($s); }
function checksums(PDO $p, array $tables): array { $o = []; foreach ($tables as $t) { $r = $p->query("CHECKSUM TABLE `$t`")->fetch(PDO::FETCH_NUM); $o[$t] = $r[1]; } return $o; }
function tables(PDO $p): array { return $p->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN); }
$GLOBALS['ADMF_TODAY_OVERRIDE'] = '2026-12-15'; fwrite(STDERR, "MySQL $ver, database $db\n");
$au = []; $audit = function (string $a, string $s) use (&$au) { $au[] = [$a, $s]; };

section('prerequisite schema (Phase 6 CRM + submissions)');
run($pdo, "$root/database/phase6_crm.sql"); $sub = file_get_contents("$root/database/full_mysql_schema.sql"); preg_match('/CREATE TABLE IF NOT EXISTS submissions \(.*?\n\);/s', $sub, $m); $pdo->exec(rtrim($m[0], ';'));
$existing = array_values(array_filter(tables($pdo), fn($t) => !str_starts_with($t, 'fin_'))); ok(in_array('crm_contracts', $existing, true) && in_array('submissions', $existing, true), 'CRM and submissions tables exist');
$store = new AdmFinancePdoStore($pdo); ok(!$store->finReady(), 'before the migration the finance storage reports not ready');
$owner = ['username' => 'fin-owner', 'role' => 'owner', 'id' => 1]; $r = admf_apply($store, $owner, 'expense_add', ['entry_date' => '2026-12-01', 'category' => 'other', 'amount' => '10', 'currency' => 'EUR', 'description' => 'before migration'], $audit); ok(!$r['ok'] && $r['code'] === 503, 'before the migration a write is refused with 503 (no crash)');
ok(admf_report(admf_load($store))['currencies'] === [], 'before the migration and with an empty CRM the report is empty, not an error');

section('migration: structure, idempotency, additive');
$before = checksums($pdo, $existing); $defs = []; foreach ($existing as $t) $defs[$t] = $pdo->query("SHOW CREATE TABLE `$t`")->fetch(PDO::FETCH_NUM)[1];
run($pdo, "$root/database/phase8d_finance.sql"); run($pdo, "$root/database/phase8d_finance.sql"); run($pdo, "$root/database/phase8d_finance.sql");
$new = array_values(array_diff(tables($pdo), $existing)); sort($new); ok($new === ['fin_adjustment', 'fin_expense_entry', 'fin_target'], 'the migration adds exactly three tables (and survives three runs)');
ok(checksums($pdo, $existing) === $before, 'every existing table is byte-for-byte unchanged (CHECKSUM TABLE)'); $same = true; foreach ($existing as $t) if ($pdo->query("SHOW CREATE TABLE `$t`")->fetch(PDO::FETCH_NUM)[1] !== $defs[$t]) $same = false; ok($same, 'no existing table definition changed (SHOW CREATE TABLE)');
$info = fn(string $t) => $pdo->query("SELECT ENGINE, TABLE_COLLATION FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = '$t'")->fetch(); foreach ($new as $t) ok($info($t)['ENGINE'] === 'InnoDB' && str_starts_with((string)$info($t)['TABLE_COLLATION'], 'utf8mb4'), "$t is InnoDB utf8mb4");
$idx = fn(string $t) => $pdo->query("SELECT index_name AS idx, non_unique AS nu, GROUP_CONCAT(column_name ORDER BY seq_in_index) AS cols FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = '$t' GROUP BY index_name, non_unique")->fetchAll(PDO::FETCH_UNIQUE | PDO::FETCH_ASSOC);
ok(isset($idx('fin_expense_entry')['idx_fin_exp_date']) && isset($idx('fin_expense_entry')['idx_fin_exp_cat']) && isset($idx('fin_adjustment')['idx_fin_adj_contract']) && isset($idx('fin_adjustment')['idx_fin_adj_date']), 'the planned indexes exist');
ok(($idx('fin_target')['uq_fin_target_active']['nu'] ?? 1) == 0 && ($idx('fin_target')['uq_fin_target_active']['cols'] ?? '') === 'active_slot', 'fin_target has a UNIQUE key on the generated active_slot');
$gc = $pdo->query("SELECT generation_expression AS ge, extra AS extra FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'fin_target' AND column_name = 'active_slot'")->fetch(); ok(stripos((string)$gc['extra'], 'STORED GENERATED') !== false, 'active_slot is a STORED generated column');
$fk = (int)$pdo->query("SELECT COUNT(*) FROM information_schema.table_constraints WHERE table_schema = DATABASE() AND constraint_type = 'FOREIGN KEY' AND table_name LIKE 'fin\\_%'")->fetchColumn(); ok($fk === 0, 'no foreign key from the finance tables into the CRM (documented design)');
$pdo->exec("INSERT INTO fin_target (month, metric, amount_minor, currency, created_at) VALUES ('2026-12-01','received',1000000,'EUR',NOW())");
try { $pdo->exec("INSERT INTO fin_target (month, metric, amount_minor, currency, created_at) VALUES ('2026-12-01','received',2000000,'EUR',NOW())"); ok(false, 'a second ACTIVE target for the same month and measure is rejected'); } catch (PDOException $e) { ok($e->getCode() === '23000', 'a second ACTIVE target for the same month and measure is rejected by the database'); }
$pdo->exec("INSERT INTO fin_target (month, metric, amount_minor, currency, created_at) VALUES ('2026-12-01','mrr',500000,'EUR',NOW())"); ok(true, 'a different measure for the same month is allowed');
$pdo->exec("UPDATE fin_target SET superseded_at = NOW() WHERE metric = 'received'"); $pdo->exec("INSERT INTO fin_target (month, metric, amount_minor, currency, created_at) VALUES ('2026-12-01','received',2000000,'EUR',NOW())"); $pdo->exec("INSERT INTO fin_target (month, metric, amount_minor, currency, created_at, superseded_at) VALUES ('2026-12-01','received',3000000,'EUR',NOW(),NOW())"); ok((int)$pdo->query("SELECT COUNT(*) FROM fin_target WHERE metric='received'")->fetchColumn() === 3 && (int)$pdo->query("SELECT COUNT(*) FROM fin_target WHERE metric='received' AND superseded_at IS NULL")->fetchColumn() === 1, 'superseded history rows may repeat; exactly one stays active');
$pdo->exec('DELETE FROM fin_target'); ok($store->finReady(), 'after the migration the finance storage is ready');

section('realistic synthetic data (EUR and USD, recurring, refunds, missing data, demo records)');
$pdo->exec("INSERT INTO crm_users (username, display_name, role, password_hash, created_at) VALUES ('fin-owner','Fin Owner','owner','x',NOW())");
$mkCo = function (string $n, int $syn = 0) use ($pdo) { $pdo->prepare('INSERT INTO crm_companies (name, created_at, updated_at, is_synthetic) VALUES (?,NOW(),NOW(),?)')->execute([$n, $syn]); return (int)$pdo->lastInsertId(); };
$mkLead = function (string $kind) use ($pdo) { $pdo->prepare("INSERT INTO crm_leads (kind, message, created_at, updated_at) VALUES (?, 'synthetic', NOW(), NOW())")->execute([$kind]); return (int)$pdo->lastInsertId(); };
$mkOpp = function (int $co, string $kind, ?int $lead = null, string $stage = 'won', int $amt = 0, string $cur = 'EUR', int $syn = 0) use ($pdo) { $pdo->prepare('INSERT INTO crm_opportunities (lead_id, company_id, kind, title, stage, amount_minor, currency, created_at, updated_at, is_synthetic) VALUES (?,?,?,?,?,?,?,NOW(),NOW(),?)')->execute([$lead, $co, $kind, 'Synthetic ' . $kind, $stage, $amt, $cur, $syn]); return (int)$pdo->lastInsertId(); };
$mkK = function (int $co, ?int $opp, string $bp, int $amt, string $cur, string $start, ?string $end = null, string $status = 'active', ?string $renew = null, int $syn = 0) use ($pdo) { $pdo->prepare("INSERT INTO crm_contracts (opportunity_id, company_id, status, start_date, end_date, billing_period, amount_minor, currency, renewal_date, confirmed_at, created_at, is_synthetic) VALUES (?,?,?,?,?,?,?,?,?,?,NOW(),?)")->execute([$opp, $co, $status, $start, $end, $bp, $amt, $cur, $renew, $status === 'draft' ? null : '2026-05-01 10:00:00', $syn]); return (int)$pdo->lastInsertId(); };
$mkRev = function (int $k, string $kind, int $amt, string $date, string $cur = 'EUR', int $syn = 0) use ($pdo) { $pdo->prepare('INSERT INTO crm_revenue_entries (contract_id, kind, amount_minor, currency, entry_date, created_at, is_synthetic) VALUES (?,?,?,?,?,NOW(),?)')->execute([$k, $kind, $amt, $cur, $date, $syn]); };
$cA = $mkCo('Aster Labs'); $cB = $mkCo('Borealis AI'); $cC = $mkCo('Cedar Systems'); $cD = $mkCo('Delta News'); $cE = $mkCo('Ember Partners'); $cF = $mkCo('Café Zürich — 日本');
$lA = $mkLead('advertising'); $lD = $mkLead('advertising'); $pdo->prepare("INSERT INTO crm_campaigns (company_id, lead_id, package, title, status, quote_minor, quote_currency, created_at, updated_at) VALUES (?,?,?,?,?,?,?,NOW(),NOW())")->execute([$cA, $lA, 'featured_placement', 'Aster featured', 'live', 150000, 'EUR']); $pdo->prepare("INSERT INTO crm_campaigns (company_id, lead_id, package, title, status, quote_minor, quote_currency, created_at, updated_at) VALUES (?,?,?,?,?,?,?,NOW(),NOW())")->execute([$cD, $lD, 'newsletter_sponsorship', 'Delta newsletter', 'in_review', 90000, 'EUR']);
$k1 = $mkK($cA, $mkOpp($cA, 'advertising', $lA), 'monthly', 150000, 'EUR', '2026-06-01'); $k2 = $mkK($cB, $mkOpp($cB, 'development'), 'monthly', 800000, 'EUR', '2026-08-01', null, 'active', '2027-01-10'); $k3 = $mkK($cC, $mkOpp($cC, 'development'), 'one_off', 2400000, 'EUR', '2026-10-01', '2026-11-30');
$k4 = $mkK($cD, $mkOpp($cD, 'advertising', $lD), 'monthly', 90000, 'EUR', '2026-09-01'); $k5 = $mkK($cE, $mkOpp($cE, 'partnership'), 'annual', 360000, 'USD', '2026-04-01'); $k6 = $mkK($cF, null, 'monthly', 12000, 'EUR', '2026-11-01'); $k7 = $mkK($cA, null, 'monthly', 777000, 'EUR', '2026-11-01', null, 'draft');
foreach (['2026-06', '2026-07', '2026-08', '2026-09', '2026-10', '2026-11'] as $mo) { $mkRev($k1, 'invoiced', 150000, "$mo-02"); $mkRev($k1, 'received', 150000, "$mo-12"); } foreach (['2026-08', '2026-09', '2026-10', '2026-11'] as $mo) { $mkRev($k2, 'invoiced', 800000, "$mo-02"); $mkRev($k2, 'received', 800000, "$mo-14"); } $mkRev($k2, 'invoiced', 800000, '2026-12-02'); $mkRev($k3, 'invoiced', 2400000, '2026-10-05'); $mkRev($k3, 'received', 2400000, '2026-11-18'); foreach (['2026-09', '2026-10', '2026-11'] as $mo) { $mkRev($k4, 'invoiced', 90000, "$mo-03"); $mkRev($k4, 'received', 90000, "$mo-15"); } $mkRev($k5, 'invoiced', 360000, '2026-04-03', 'USD'); $mkRev($k5, 'received', 360000, '2026-04-20', 'USD'); $mkRev($k6, 'invoiced', 12000, '2026-11-03');
$mkOpp($cA, 'development', null, 'proposal', 4000000); $mkOpp($cB, 'advertising', null, 'discovery', 600000);
foreach ([[49, 'USD', 'paid'], [49, 'USD', 'paid'], [99, 'USD', 'unpaid'], [0, 'USD', 'not_required'], [99, 'EUR', 'paid']] as $i => [$p, $c, $ps]) $pdo->prepare("INSERT INTO submissions (name, category, website, short_desc, plan, price, currency, status, payment_status) VALUES (?,?,?,?,?,?,?,?,?)")->execute(["Legacy $i", 'Writing', 'https://legacy.example.com', 'Legacy synthetic submission', $p > 0 ? 'featured' : 'free', $p, $c, 'approved', $ps]);
$crmTables = array_values(array_filter(tables($pdo), fn($t) => str_starts_with($t, 'crm_') || $t === 'submissions')); $crmBefore = checksums($pdo, $crmTables);

section('reuse of the Phase 6 revenue calculations (no duplicated revenue logic)');
$rep = admf_report(admf_load($store)); $crm = crm_revenue_summary($pdo, '2026-12-15');
foreach (['EUR', 'USD'] as $c) { $a = $rep['currencies'][$c]; $b = $crm[$c]; foreach (['mrr', 'arr', 'recognized', 'contracted', 'invoiced', 'received', 'forecast'] as $f) ok($a[$f] === $b[$f], "$c $f equals crm_revenue_summary ($f = {$a[$f]})"); }
ok(array_keys($rep['currencies']) === ['EUR', 'USD'], 'EUR and USD are separate reports');
$e = $rep['currencies']['EUR']; ok($e['streams']['featured']['received'] === 900000 && $e['streams']['newsletter']['received'] === 270000 && $e['streams']['retainer']['received'] === 3200000 && $e['streams']['project']['received'] === 2400000 && $e['streams']['unclassified']['contracts'] === 2, 'streams from the real opportunity kind and campaign package join (2 unclassified: no opportunity)');
ok($rep['legacy']['USD'] === ['paid_count' => 2, 'paid_minor' => 9800, 'unpaid_count' => 1] && $rep['legacy']['EUR']['paid_minor'] === 9900 && $e['received'] === $crm['EUR']['received'], 'legacy listing payments are read from submissions, separate, and not added to CRM received');
ok($e['outstanding'] === 800000 + 12000 && $e['mrr'] === 150000 + 800000 + 90000 + 12000, 'outstanding and MRR from real rows (draft contract excluded)');
$mkK($cE, null, 'monthly', 99999999, 'EUR', '2026-06-01', null, 'active', null, 1); $mkRev($k1, 'received', 55555555, '2026-12-01', 'EUR', 1); $rep2 = admf_report(admf_load($store)); ok($rep2['currencies']['EUR']['mrr'] === $e['mrr'] && $rep2['currencies']['EUR']['received'] === $e['received'] && $rep2['synthetic_excluded']['contracts'] === 1 && $rep2['synthetic_excluded']['revenue'] === 1, 'synthetic contracts and payments (is_synthetic = 1) are excluded');
$crm2 = crm_revenue_summary($pdo, '2026-12-15'); ok($crm2['EUR']['received'] > $e['received'], 'for contrast: the CRM summary itself counts the synthetic rows, the finance report does not (documented difference)');

section('finance store and engine against real MySQL');
$good = ['entry_date' => '2026-12-10', 'category' => 'marketing', 'amount' => '120.50', 'currency' => 'EUR', 'description' => 'Café — 日本 ads', 'recurrence' => 'none', 'vendor' => 'Vendor ü', 'reference' => 'DOC-1'];
$r = admf_apply($store, $owner, 'expense_add', $good, $audit); $row = $pdo->query('SELECT * FROM fin_expense_entry ORDER BY id DESC LIMIT 1')->fetch(); ok($r['ok'] && $row['amount_minor'] == 12050 && $row['description'] === 'Café — 日本 ads' && $row['vendor'] === 'Vendor ü' && $row['created_by'] !== null && (int)$row['is_synthetic'] === 0, 'an expense is stored with utf8mb4 text, minor units and the CRM user id');
admf_apply($store, $owner, 'expense_add', ['entry_date' => '2026-08-15', 'category' => 'hosting_infrastructure', 'amount' => '200', 'description' => 'Hosting', 'recurrence' => 'monthly'] + $good, $audit); admf_apply($store, $owner, 'expense_add', ['entry_date' => '2026-03-10', 'category' => 'software_tools', 'amount' => '1200', 'description' => 'Licence', 'recurrence' => 'annual'] + $good, $audit); admf_apply($store, $owner, 'expense_add', ['entry_date' => '2026-12-03', 'category' => 'other', 'amount' => '50', 'currency' => 'USD', 'description' => 'USD cost'] + $good, $audit);
$rep3 = admf_report(admf_load($store)); ok($rep3['currencies']['EUR']['expenses'] === 12050 + 5 * 20000 + 120000 && $rep3['currencies']['USD']['expenses'] === 5000, 'recurring monthly and annual expenses are expanded per month, per currency, from real rows');
$id = (int)$pdo->query('SELECT id FROM fin_expense_entry ORDER BY id LIMIT 1')->fetchColumn(); $r = admf_apply($store, $owner, 'expense_void', ['id' => $id, 'reason' => 'entered twice'], $audit); $v = $pdo->query("SELECT voided_at, void_reason FROM fin_expense_entry WHERE id = $id")->fetch(); ok($r['ok'] && $v['voided_at'] !== null && $v['void_reason'] === 'entered twice' && (int)$pdo->query('SELECT COUNT(*) FROM fin_expense_entry')->fetchColumn() === 4, 'voiding sets the void columns and keeps the row');
ok(admf_apply($store, $owner, 'expense_void', ['id' => $id, 'reason' => 'twice again'], $audit)['code'] === 409 && admf_apply($store, $owner, 'expense_void', ['id' => 999999, 'reason' => 'does not exist'], $audit)['code'] === 404, 'double void 409 and unknown id 404 from real rows');
$n = (int)$pdo->query('SELECT COUNT(*) FROM fin_expense_entry')->fetchColumn(); $bad = $store->addExpense(['entry_date' => '2026-12-01', 'category' => 'other', 'vendor' => '', 'description' => 'currency too long', 'amount_minor' => 100, 'currency' => 'EURO', 'recurrence' => 'none', 'recurrence_end' => null, 'reference' => ''], 'x'); ok(!$bad['ok'] && (int)$pdo->query('SELECT COUNT(*) FROM fin_expense_entry')->fetchColumn() === $n && !$pdo->inTransaction(), 'a database error inside a write rolls back cleanly and returns a failure, not an exception');
$k1id = $k1; $r = admf_apply($store, $owner, 'adjustment_add', ['kind' => 'refund', 'contract_id' => $k1id, 'amount' => '500', 'entry_date' => '2026-12-05', 'reference' => 'RF-1'], $audit); ok($r['ok'] && $pdo->query('SELECT currency FROM fin_adjustment ORDER BY id DESC LIMIT 1')->fetchColumn() === 'EUR', 'a refund against a real CRM contract is stored with the contract currency');
ok(!admf_apply($store, $owner, 'adjustment_add', ['kind' => 'refund', 'contract_id' => $k1id, 'amount' => '99999', 'entry_date' => '2026-12-05'], $audit)['ok'] && !admf_apply($store, $owner, 'adjustment_add', ['kind' => 'credit', 'contract_id' => $k1id, 'amount' => '99999', 'entry_date' => '2026-12-05'], $audit)['ok'] && !admf_apply($store, $owner, 'adjustment_add', ['kind' => 'refund', 'contract_id' => $k7 ?? 0, 'amount' => '1', 'entry_date' => '2026-12-05'], $audit)['ok'], 'refund and credit limits and the confirmed-contract rule hold against real CRM data');
admf_apply($store, $owner, 'adjustment_add', ['kind' => 'credit', 'contract_id' => $k4, 'amount' => '900', 'entry_date' => '2026-12-04', 'reference' => 'CN-1'], $audit); $rep4 = admf_report(admf_load($store)); $e4 = $rep4['currencies']['EUR']; ok($e4['refunds'] === 50000 && $e4['credits'] === 90000 && $e4['net_income'] === $e['received'] - 50000 && $e4['outstanding'] === max(0, $e4['net_invoiced'] - $e4['received']), 'refunds and credit notes flow into net income and outstanding');
$aid = (int)$pdo->query('SELECT id FROM fin_adjustment ORDER BY id LIMIT 1')->fetchColumn(); ok(admf_apply($store, $owner, 'adjustment_void', ['id' => $aid, 'reason' => 'wrong contract'], $audit)['ok'] && admf_report(admf_load($store))['currencies']['EUR']['refunds'] === 0, 'a voided refund stops counting and the row remains');
$r1 = admf_apply($store, $owner, 'target_set', ['month' => '2026-12', 'metric' => 'received', 'amount' => '10000', 'label' => 'first'], $audit); $r2 = admf_apply($store, $owner, 'target_set', ['month' => '2026-12', 'metric' => 'received', 'amount' => '12000'], $audit); ok($r1['ok'] && $r2['ok'] && (int)$pdo->query("SELECT COUNT(*) FROM fin_target WHERE metric='received'")->fetchColumn() === 2 && (int)$pdo->query("SELECT COUNT(*) FROM fin_target WHERE metric='received' AND superseded_at IS NULL")->fetchColumn() === 1, 'setting a target twice keeps both rows with exactly one active');
$pdo->exec("INSERT INTO fin_target (month, metric, amount_minor, currency, created_at) VALUES ('2027-01-01','received',5,'EUR',NOW())"); $rr = $store->setTarget('2027-01', 'received', 700, 'x', 'owner'); ok($rr['ok'] && (int)$pdo->query("SELECT amount_minor FROM fin_target WHERE month='2027-01-01' AND superseded_at IS NULL")->fetchColumn() === 700, 'superseding works on an existing active row');
$t = $store->targets(); ok(count($t) >= 4 && isset($t[0]['month']), 'targets() reads back');
$after = checksums($pdo, $crmTables); unset($crmBefore['crm_revenue_entries'], $after['crm_revenue_entries'], $crmBefore['crm_contracts'], $after['crm_contracts']); ok($after === $crmBefore, 'finance operations did not change any CRM or submissions table (data inserted by this test aside)');

section('every Finance screen renders from real MySQL data');
foreach (['overview' => [], 'revenue' => ['view' => 'revenue'], 'advertising' => ['view' => 'advertising'], 'projects' => ['view' => 'projects'], 'expenses' => ['view' => 'expenses'], 'refunds' => ['view' => 'refunds'], 'targets' => ['view' => 'targets', 'calc' => '1', 'v_contract' => '2000'], 'exports' => ['view' => 'exports']] as $name => $g) { $h = admf_body($store, $owner, $g); ok(strlen($h) > 2000 && strpos($h, 'Fatal') === false && strpos($h, 'Warning') === false && strpos($h, 'Not tracked') !== false, "$name renders from real data"); }
$h = admf_body($store, $owner, ['view' => 'projects']); ok(strpos($h, 'Cedar Systems') !== false && strpos($h, 'Borealis AI') !== false && strpos($h, 'Café Zürich') === false, 'projects lists the development contracts from MySQL');
foreach (array_keys(ADMF_EXPORTS) as $k) { $x = admf_export($k, admf_report(admf_load($store)), admf_load($store)); ok($x !== null && strlen($x[1]) > 40, "export $k works on real data"); }

section('scale: 3,000 contracts, 30,000 payment records, 3,000 expenses on MySQL');
$t0 = microtime(true); $pdo->beginTransaction(); $co = $cA;
for ($i = 1; $i <= 3000; $i++) { $start = gmdate('Y-m-d', strtotime('2025-01-01 +' . ($i % 700) . ' days')); $pdo->exec("INSERT INTO crm_contracts (company_id, status, start_date, billing_period, amount_minor, currency, confirmed_at, created_at) VALUES ($co, 'active', '$start', 'monthly', " . (10000 + $i) . ", '" . ($i % 7 === 0 ? 'USD' : 'EUR') . "', '2025-01-01 00:00:00', NOW())"); $kid = (int)$pdo->lastInsertId(); $rows = []; for ($j = 0; $j < 5; $j++) { $d = gmdate('Y-m-d', strtotime("$start +" . ($j * 30) . ' days')); $c = $i % 7 === 0 ? 'USD' : 'EUR'; $rows[] = "($kid,'invoiced',10000,'$c','$d',NOW())"; $rows[] = "($kid,'received',10000,'$c','$d',NOW())"; } $pdo->exec('INSERT INTO crm_revenue_entries (contract_id, kind, amount_minor, currency, entry_date, created_at) VALUES ' . implode(',', $rows)); }
for ($i = 1; $i <= 3000; $i++) { $d = gmdate('Y-m-d', strtotime('2026-01-01 +' . ($i % 340) . ' days')); $rc = ['none', 'monthly', 'annual'][$i % 3]; $pdo->exec("INSERT INTO fin_expense_entry (entry_date, category, description, amount_minor, currency, recurrence, created_at) VALUES ('$d', '" . array_keys(ADMF_CATEGORIES)[$i % 7] . "', 'Scale expense $i', " . (1000 + $i) . ", 'EUR', '$rc', NOW())"); } $pdo->commit();
fwrite(STDERR, sprintf("  (seeded in %.1fs)\n", microtime(true) - $t0)); $t1 = microtime(true); $d = admf_load($store); $rs = admf_report($d); $tl = microtime(true) - $t1; $t2 = microtime(true); $hh = admf_body($store, $owner, []); $tp = microtime(true) - $t2; $hr = admf_body($store, $owner, ['view' => 'revenue']); $he = admf_body($store, $owner, ['view' => 'expenses']); $ta = microtime(true) - $t2; $mem = memory_get_peak_usage(true) / 1048576;
fwrite(STDERR, sprintf("  (load+report %.2fs; overview %.2fs; three pages %.2fs; peak memory %.0f MB)\n", $tl, $tp, $ta, $mem)); ok($tl < 8 && $ta < 12 && $mem < 400, 'the report and pages stay within bounds at 3,000 contracts / 30,000 payments / 3,000 expenses');
ok($rs['currencies']['EUR']['has_revenue'] && $rs['counts']['revenue'] >= 30000 && strlen($hh) > 5000 && strlen($hr) > 5000 && strlen($he) > 5000, 'all pages render with the large data set');
$cnt = (int)preg_match_all('/class="tRow"/', $he); ok($cnt <= 100, 'the expense list is capped at 100 rows (' . $cnt . ')');

section('least-privilege database user (the grants documented for deployment)');
$admin->exec("CREATE USER '$appUser'@'%' IDENTIFIED BY '$appPw'"); foreach (['crm_contracts', 'crm_companies', 'crm_opportunities', 'crm_campaigns', 'crm_revenue_entries', 'crm_users', 'submissions'] as $t) $admin->exec("GRANT SELECT ON `$db`.`$t` TO '$appUser'@'%'"); foreach (['fin_expense_entry', 'fin_target', 'fin_adjustment'] as $t) $admin->exec("GRANT SELECT, INSERT, UPDATE ON `$db`.`$t` TO '$appUser'@'%'");
$lp = new PDO("mysql:host=$host;port=3306;dbname=$db", $appUser, $appPw, $opt); $ls = new AdmFinancePdoStore($lp); ok($ls->finReady(), 'the least-privilege user sees the finance storage as ready');
$rl = admf_report(admf_load($ls)); $rfull = admf_report(admf_load($store)); ok($rl['currencies']['EUR']['mrr'] === $rfull['currencies']['EUR']['mrr'] && $rl['currencies']['EUR']['received'] === $rfull['currencies']['EUR']['received'] && $rl['legacy'] === $rfull['legacy'], 'reports read identically with SELECT-only access to the CRM');
$r = admf_apply($ls, $owner, 'expense_add', ['description' => 'via least privilege'] + $good, $audit); ok($r['ok'], 'writes work with INSERT on the finance tables');
$idl = (int)$lp->query("SELECT id FROM fin_expense_entry WHERE description = 'via least privilege'")->fetchColumn(); ok(admf_apply($ls, $owner, 'expense_void', ['id' => $idl, 'reason' => 'least privilege void'], $audit)['ok'], 'void (SELECT ... FOR UPDATE, then UPDATE) works with SELECT and UPDATE only');
ok(admf_apply($ls, $owner, 'target_set', ['month' => '2027-03', 'metric' => 'mrr', 'amount' => '100'], $audit)['ok'] && admf_apply($ls, $owner, 'adjustment_add', ['kind' => 'refund', 'contract_id' => $k2, 'amount' => '10', 'entry_date' => '2026-12-05'], $audit)['ok'], 'targets and adjustments work with the documented grants');
foreach (["INSERT INTO crm_contracts (company_id, amount_minor, currency, created_at) VALUES (1, 1, 'EUR', NOW())", "UPDATE crm_revenue_entries SET amount_minor = 1", "DELETE FROM crm_revenue_entries", "DELETE FROM fin_expense_entry", "DROP TABLE fin_target", "UPDATE submissions SET payment_status = 'paid'", "ALTER TABLE fin_target ADD x INT"] as $sql) { try { $lp->exec($sql); ok(false, "denied: $sql"); } catch (PDOException $e) { ok(in_array($e->getCode(), ['42000', '1142', '1044'], true) || stripos($e->getMessage(), 'denied') !== false, 'denied: ' . substr($sql, 0, 48)); } }

section('rollback and re-apply');
$finBefore = (int)$pdo->query('SELECT COUNT(*) FROM fin_expense_entry')->fetchColumn(); ok($finBefore > 0, 'there is finance data to roll back');
$crmNow = checksums($pdo, $existing); run($pdo, "$root/database/phase8d_rollback.sql"); run($pdo, "$root/database/phase8d_rollback.sql"); ok(array_values(array_filter(tables($pdo), fn($t) => str_starts_with($t, 'fin_'))) === [], 'the rollback removes exactly the three finance tables (and is safe to run twice)');
ok(checksums($pdo, $existing) === $crmNow, 'the rollback leaves every CRM and other table untouched'); ok(!(new AdmFinancePdoStore($pdo))->finReady(), 'after the rollback the module reports storage not installed');
$h = admf_body(new AdmFinancePdoStore($pdo), $owner, ['view' => 'expenses']); ok(strpos($h, 'Finance storage is not installed') !== false && strpos($h, 'fin_expense_add') === false && strpos(admf_body(new AdmFinancePdoStore($pdo), $owner, []), 'No revenue is recorded') === false, 'after the rollback revenue pages still read the CRM and write forms disappear');
run($pdo, "$root/database/phase8d_finance.sql"); ok((new AdmFinancePdoStore($pdo))->finReady() && (int)$pdo->query('SELECT COUNT(*) FROM fin_expense_entry')->fetchColumn() === 0, 'a fresh re-apply after the rollback works and starts empty');

section('Phase 8C regression on real MySQL (migration and store smoke test)');
preg_match('/CREATE TABLE IF NOT EXISTS categories \(.*?\n\);/s', $sub, $mc); preg_match('/CREATE TABLE IF NOT EXISTS tools \(.*?\n\);/s', $sub, $mt); $pdo->exec(rtrim($mc[0], ';')); $pdo->exec(rtrim($mt[0], ';'));
$tb = checksums($pdo, ['tools', 'categories', 'submissions']); run($pdo, "$root/database/phase8c_tools.sql"); run($pdo, "$root/database/phase8c_tools.sql"); ok(checksums($pdo, ['tools', 'categories', 'submissions']) === $tb && count(array_intersect(tables($pdo), ['adm_tool_revision', 'adm_tool_feature', 'adm_submission_review'])) === 3, 'the Phase 8C migration is additive and idempotent on MySQL');
$ts = new AdmToolPdoStore($pdo); ok(AdmToolPdoStore::ready($pdo), '8C storage is ready'); $own = ['username' => 'fin-owner', 'role' => 'owner']; $a8 = function ($a, $b, $c) {};
$tool = ['name' => 'Smoke Tool', 'category' => 'Writing', 'short' => 'A synthetic smoke test tool description.', 'pricing_type' => 'Free', 'website' => 'https://smoke.example.com', 'features' => 'one', 'tags' => 'smoke, test'];
$r = admt_apply($ts, $own, 'create', $tool, $a8); $g = $ts->get('smoke-tool'); ok($r['ok'] && $g && $g['status'] === 'draft' && $g['category'] === 'Writing' && $g['tags'] === ['smoke', 'test'] && (int)$pdo->query('SELECT COUNT(*) FROM categories WHERE name = \'Writing\'')->fetchColumn() === 1, '8C: create makes a draft and the public category row on demand (MySQL)');
$r = admt_apply($ts, $own, 'publish', ['slug' => 'smoke-tool', 'version' => $g['_version']], $a8); ok($r['ok'] && $ts->get('smoke-tool')['status'] === 'published', '8C: publish');
$stale = admt_apply($ts, $own, 'edit', $tool + ['slug' => 'smoke-tool', 'version' => 0, 'name' => 'Stale'], $a8); ok(!$stale['ok'] && $stale['code'] === 409, '8C: a stale edit is refused by the revision key');
$v = $ts->get('smoke-tool')['_version']; $r = admt_apply($ts, $own, 'edit', ['slug' => 'smoke-tool', 'version' => $v, 'name' => 'Smoke Tool Two'] + $tool, $a8); ok($r['ok'] && $ts->get('smoke-tool')['name'] === 'Smoke Tool Two' && count($ts->revisions('smoke-tool')) === 3, '8C: edit and history');
$r = admt_apply($ts, $own, 'bulk_apply', ['op' => 'add_tag', 'tag' => 'bulk', 'sel' => ['smoke-tool'], 'ver' => ['smoke-tool' => $ts->get('smoke-tool')['_version']]], $a8); ok($r['ok'] && in_array('bulk', $ts->get('smoke-tool')['tags'], true), '8C: bulk apply in one transaction');
$r = admt_apply($ts, $own, 'feature_add', ['slug' => 'smoke-tool', 'level' => 1, 'ends_on' => '2027-01-31'], $a8); $gf = $ts->get('smoke-tool'); ok($r['ok'] && $gf['featured_level'] === 1 && $gf['featured_until'] === '2027-01-31', '8C: a featured placement mirrors into the tools columns');
$pdo->exec("INSERT INTO submissions (name, category, website, short_desc, plan, price, currency, status, payment_status) VALUES ('Sub Tool','Writing','https://sub.example.com','A synthetic submitted tool description.','free',0,'USD','pending','not_required')"); $sid = (int)$pdo->lastInsertId();
$r = admt_apply($ts, $own, 'submission_approve', ['id' => $sid, 'category' => 'Writing'], $a8); ok($r['ok'] && $ts->get('sub-tool')['status'] === 'draft' && $pdo->query("SELECT status FROM submissions WHERE id = $sid")->fetchColumn() === 'approved' && $pdo->query("SELECT decision FROM adm_submission_review WHERE submission_id = $sid")->fetchColumn() === 'approved', '8C: submission approval creates a draft and records the decision (MySQL)');
ok(admt_apply($ts, $own, 'submission_approve', ['id' => $sid, 'category' => 'Writing'], $a8)['code'] === 409, '8C: a decided submission cannot be decided twice');
$r = admt_apply($ts, $own, 'delete', ['slug' => 'smoke-tool', 'version' => $ts->get('smoke-tool')['_version'], 'confirm' => '1'], $a8); ok($r['ok'] && $ts->get('smoke-tool')['status'] === 'deleted' && (int)$pdo->query("SELECT COUNT(*) FROM tools WHERE slug = 'smoke-tool'")->fetchColumn() === 1, '8C: soft delete keeps the row');
run($pdo, "$root/database/phase8c_rollback.sql"); ok(count(array_intersect(tables($pdo), ['adm_tool_revision', 'adm_tool_feature', 'adm_submission_review'])) === 0 && (int)$pdo->query('SELECT COUNT(*) FROM tools')->fetchColumn() >= 2, '8C: its rollback removes only its three tables and keeps the tools');

echo "\nPASSED: $pass  FAILED: $fail   (MySQL $ver)\n"; exit($fail ? 1 : 0);
